fn prime_fib(n: isize) -> isize {
    let mut a = 0;
    let mut b = 1;
    let mut count = 0;

    while count < n {
        let temp = a + b;
        a = b;
        b = temp;

        if is_prime(temp) {
            count += 1;
        }
    }

    temp
}

fn is_prime(num: isize) -> bool {
    if num <= 1 {
        return false;
    }
    if num <= 3 {
        return true;
    }
    if num % 2 == 0 || num % 3 == 0 {
        return false;
    }
    let mut i = 5;
    while i * i <= num {
        if num % i == 0 || num % (i + 2) == 0 {
            return false;
        }
        i += 6;
    }
    true
}
