fn is_nested(string: String) -> bool {
    let mut balance = 0;
    let mut has_nested = false;

    for c in string.chars() {
        match c {
            '[' => balance += 1,
            ']' => {
                balance -= 1;
                if balance < 0 {
                    return false; // More closing brackets than opening
                }
                if balance == 1 {
                    has_nested = true; // Found a nested pair
                }
            }
            _ => {}
        }
    }

    has_nested && balance == 0 // True if there is at least one nested pair and all brackets are balanced
}
