fn get_total_number_of_sequences(m: isize, n: isize) -> isize {
    if m < 2 || n < 1 {
        return 0;
    }

    let mut dp = vec![vec![0; n + 1]; m + 1];
    dp[0][0] = 1; // Base case: there's one way to have an empty sequence

    for i in 1..=m {
        for j in 1..=n {
            if i >= 2 * j {
                dp[i][j] = dp[i - 1][j] + dp[i - 2 * j][j];
            } else {
                dp[i][j] = dp[i - 1][j];
            }
        }
    }

    dp[m][n]
}
```

