fn lcs_of_three(X: String, Y: String, Z: String) -> isize {
    let m = X.len();
    let n = Y.len();
    let p = Z.len();

    let mut dp = vec![vec![0; p + 1]; n + 1];

    for i in 1..=m {
        for j in 1..=n {
            for k in 1..=p {
                if X.chars().nth(i - 1) == Y.chars().nth(j - 1) && Y.chars().nth(j - 1) == Z.chars().nth(k - 1) {
                    dp[i][j][k] = dp[i - 1][j - 1][k - 1] + 1;
                } else {
                    dp[i][j][k] = std::cmp::max(std::cmp::max(dp[i - 1][j][k], dp[i][j - 1][k]), dp[i][j][k - 1]);
                }
            }
        }
    }

    dp[m][n][p]
}
